import{_ as a}from"./chunks/pdf-import-triage.VhDzuCgc.js";import{_ as s}from"./chunks/pdf-import-result.CIosTXBj.js";import{_ as t,o as i,c as n,a2 as o}from"./chunks/framework.CDEKL17z.js";const F=JSON.parse('{"title":"Knowledge base","description":"","frontmatter":{},"headers":[],"relativePath":"guide/knowledge-base.md","filePath":"guide/knowledge-base.md"}'),r={name:"guide/knowledge-base.md"};function h(l,e,d,p,k,g){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="knowledge-base" tabindex="-1">Knowledge base <a class="header-anchor" href="#knowledge-base" aria-label="Permalink to &quot;Knowledge base&quot;">​</a></h1><p>Each tenant can have a set of markdown documents the bot searches when a visitor asks a factual question - hours, policies, FAQs, product details. Retrieval is grounded: when nothing relevant is found, the bot says it doesn&#39;t know instead of guessing.</p><h2 id="adding-documents" tabindex="-1">Adding documents <a class="header-anchor" href="#adding-documents" aria-label="Permalink to &quot;Adding documents&quot;">​</a></h2><p><strong>Tenant → Knowledge base.</strong> Paste markdown with a title, save - the document is chunked, embedded and searchable immediately. Saving under an existing title replaces that document.</p><p>Two rules make retrieval precise:</p><ol><li><strong>Structure with headings.</strong> Chunking is heading-aware: each <code>##</code> section becomes a retrieval unit with its breadcrumb attached. One fact per section beats one wall of text.</li><li><strong>Only counter-safe facts.</strong> Everything here can reach a visitor. Nothing internal, no wholesale prices, nothing you would not say out loud at the counter.</li></ol><h2 id="import-from-a-pdf" tabindex="-1">Import from a PDF <a class="header-anchor" href="#import-from-a-pdf" aria-label="Permalink to &quot;Import from a PDF&quot;">​</a></h2><p>Facts often already live in a PDF - a handbook, a flyer, a policy sheet. <strong>Tenant → Knowledge base → Import from a PDF</strong> walks it in, and the design principle is that the free work happens first:</p><ol><li><strong>Analyze (free, no model).</strong> The text is read out of the file, and mechanical junk - repeated headers and footers, page numbers, table-of-contents dot lines - is stripped deterministically. You get a plain-words cost estimate for the optional AI step <em>before</em> deciding anything, plus targeted warnings: a scanned PDF (photos of pages, nothing to read), table-heavy content (prices belong in live tools, not the KB), or a file big enough to be worth splitting.</li></ol><p><img src="'+a+'" alt="Free analysis: junk stripped, token estimate, suggestions"></p><ol start="2"><li><p><strong>Trim.</strong> The text box is the selection tool: delete anything customers never ask about, and the estimate updates as you cut.</p></li><li><p><strong>Tidy with AI - or skip it.</strong> The one paid step carries its price on the button, and reports the tokens actually used afterwards. The model reorganizes the text into short <code>##</code> sections (the shape retrieval likes) but invents nothing; read the result before saving, because you know the facts.</p></li></ol><p><img src="'+s+`" alt="After the AI pass: sectioned markdown, actual usage reported"></p><ol start="4"><li><strong>Save &amp; embed</strong> - from here it is a normal document like any other.</li></ol><p>A green estimate means &quot;about one conversation&#39;s worth&quot; - just go ahead. The gauge exists to catch the accidental 300-page upload, not to make small imports feel expensive.</p><p>Owner-friendly, screen-by-screen version: <a href="./../owner/import-a-pdf">Turn a PDF into knowledge</a>.</p><h2 id="wiring-it-to-the-bot" tabindex="-1">Wiring it to the bot <a class="header-anchor" href="#wiring-it-to-the-bot" aria-label="Permalink to &quot;Wiring it to the bot&quot;">​</a></h2><p>Enable the <strong><code>search_kb</code></strong> tool pack on the tenant page. Without it, the documents exist but the bot never reads them.</p><h2 id="checking-quality" tabindex="-1">Checking quality <a class="header-anchor" href="#checking-quality" aria-label="Permalink to &quot;Checking quality&quot;">​</a></h2><p>The table shows a chunk count per document - one giant chunk or fifty tiny ones is a sign the headings need work. Developers with a repo clone can go further:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kb:ingest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tenant-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # bulk-ingest kb/&lt;slug&gt;/*.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kb:eval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tenant-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # recall@k: does the right doc come back?</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:answers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tenant-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # judge-graded: is the final ANSWER right?</span></span></code></pre></div><p>The recall eval measures retrieval; the answers eval sends real chat turns and has a second model grade each reply for faithfulness (nothing invented) and completeness (the required facts arrive) - numbers, not feelings.</p><h2 id="backup-and-bulk-editing-csv" tabindex="-1">Backup and bulk editing (CSV) <a class="header-anchor" href="#backup-and-bulk-editing-csv" aria-label="Permalink to &quot;Backup and bulk editing (CSV)&quot;">​</a></h2><p><strong>Export CSV</strong> on the Knowledge base page downloads every document as a two-column spreadsheet (title, content). Edit it in Excel or Google Sheets - fix facts, add rows - then <strong>Import from CSV</strong> brings it back: rows match by title, changed documents are re-embedded, unchanged ones are skipped. Export before big edits and you always have a restore point.</p><h2 id="instant-repeat-answers" tabindex="-1">Instant repeat answers <a class="header-anchor" href="#instant-repeat-answers" aria-label="Permalink to &quot;Instant repeat answers&quot;">​</a></h2><p>Common opening questions (&quot;what time do you open?&quot;) are served from a semantic cache: an answer already given for a near-identical first message returns instantly, at zero model cost. The cache clears itself whenever you save or delete knowledge or tenant settings, so editing a fact never leaves a stale cached answer behind.</p>`,25)])])}const b=t(r,[["render",h]]);export{F as __pageData,b as default};
